/* [KD] Reserve the dots space before the script adds them: without it the featured post and everything below drop 32px when the dots appear, which PageSpeed counts as layout shift (CLS). Reserved height = 8px margin + 24px dots */
#slider-widget.sldO:not(.kSld):has(>.widget+.widget){padding-bottom:32px}
@media screen and (max-width:640px){#slider-widget.sldO:not(.kSld):has(>.widget+.widget){padding-bottom:42px}}
